use crate::{Theme, ThemeError, Writer};
use std::path::PathBuf;
use std::process::Command;

pub struct Ghostty;

impl Writer for Ghostty {
    fn name(&self) -> &'static str {
        "ghostty"
    }

    fn output_path(&self) -> PathBuf {
        crate::home().join(".config/ghostty/themes/active")
    }

    fn enabled(&self) -> bool {
        crate::app_enabled("ghostty", ".config/ghostty")
    }

    fn generate(&self, theme: &Theme) -> Result<String, ThemeError> {
        let t = theme;
        Ok(format!(
            "# Generated by theme-manager. Do not edit manually.\n\
             # To use: add this line to ~/.config/ghostty/config:\n\
             #   config-file = ~/.config/ghostty/themes/active\n\
             #\n\
             palette = 0={}\n\
             palette = 1={}\n\
             palette = 2={}\n\
             palette = 3={}\n\
             palette = 4={}\n\
             palette = 5={}\n\
             palette = 6={}\n\
             palette = 7={}\n\
             palette = 8={}\n\
             palette = 9={}\n\
             palette = 10={}\n\
             palette = 11={}\n\
             palette = 12={}\n\
             palette = 13={}\n\
             palette = 14={}\n\
             palette = 15={}\n\
             background           = {}\n\
             background-opacity   = {}\n\
             foreground           = {}\n\
             cursor-color         = {}\n\
             selection-background = {}\n\
             selection-foreground = {}\n",
            t.require("BASE00")?,
            t.require("BASE08")?,
            t.require("BASE0B")?,
            t.require("BASE0A")?,
            t.require("BASE0D")?,
            t.require("BASE0E")?,
            t.require("BASE0C")?,
            t.require("BASE05")?,
            t.require("BASE01")?,
            t.require("BASE08")?,
            t.require("BASE0B")?,
            t.require("BASE0A")?,
            t.require("BASE0D")?,
            t.require("BASE0E")?,
            t.require("BASE0C")?,
            t.require("BASE07")?,
            t.require("BASE00")?,
            crate::get_transparency(t),
            t.require("BASE05")?,
            t.require("BASE05")?,
            t.require("BASE02")?,
            t.require("BASE05")?,
        ))
    }

    fn reload(&self) {
        const SERVICE: &str = "app-com.mitchellh.ghostty.service";

        // Ghostty's supported Linux reload path. The user service tracks the
        // main process and sends it SIGUSR2 without us having to guess a PID.
        if Command::new("systemctl")
            .args(["reload", "--user", SERVICE])
            .output()
            .map(|output| output.status.success())
            .unwrap_or(false)
        {
            eprintln!("theme-manager: [ghostty] reloaded via systemd");
            return;
        }

        // Ghostty can also be launched directly rather than through its user
        // service. SIGUSR2 is its documented config-reload signal; matching
        // the exact process name avoids signaling unrelated applications.
        match Command::new("pkill")
            .args(["--signal", "USR2", "--exact", "ghostty"])
            .status()
        {
            Ok(status) if status.success() => {
                eprintln!("theme-manager: [ghostty] reloaded via SIGUSR2");
            }
            Ok(status) if status.code() == Some(1) => {
                // No directly launched Ghostty process is running.
            }
            Ok(status) => {
                eprintln!("theme-manager: [ghostty] reload failed: pkill exited with {status}");
            }
            Err(error) => {
                eprintln!("theme-manager: [ghostty] reload failed: {error}");
            }
        }
    }
}
